const items = $input.all();
if (!items || items.length === 0) {
  const wanted = $('Config').first().json['Topic Title'];
  throw new Error(`No topic found titled "${wanted}". It must exactly match a topic already created in Phase 1.`);
}
const topic = items[0].json;
return [{ json: { topic_id: topic.id, topic_title: topic.title, channel_id: topic.channel_id } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No video at stage "script_ready" found for this topic. Run Phase 2 (phase2-script-pipeline.json) for this topic first.');
}
const video = items[0].json;
return [{ json: { id: video.id, channel_id: video.channel_id, script_id: video.script_id, stage: video.stage } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('Final script row not found — data inconsistency between videos.script_id and scripts.');
}
const row = items[0].json;
return [{ json: { script_id: row.id, content: row.content } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('Channel not found — data inconsistency, check the topics/channels tables.');
}
const c = items[0].json;
return [{ json: { channel_id: c.id, name: c.name, visual_style_notes: c.visual_style_notes, tts_voice_id: c.tts_voice_id, made_for_kids: c.made_for_kids } }];

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

const script = $('Pick Script Row').first().json.content;
const visualStyle = $('Pick Channel Row').first().json.visual_style_notes;

const system = `You are the Visual Director. Turn the finished script into a timestamped shot list.

Script: ${script}
Visual style for this channel: ${visualStyle}

For every ~5-10 second segment, specify:
- Timestamp range
- What's on screen — be specific: "satellite constellation animation, Earth
  curvature visible", not "relevant footage"
- Asset type: ai_image | ai_video | stock_video | chart | map | screen_recording
- If it's a map, chart, or flag: flag it explicitly for a fact-check pass — wrong
  borders or flags are the most common embarrassing visual error

Avoid repeating the same visual for more than ~15 consecutive seconds — the editing
QC pass will fail static or repetitive visuals.

Don't use real, identifiable people's likenesses unless they're a public figure
central to the story and the footage is properly licensed news/archival material —
flag this explicitly so Asset Sourcing verifies licensing.

Respond with JSON only, no prose outside the JSON, matching exactly this shape:
{
  "shots": [
    { "start_seconds": number, "end_seconds": number, "description": string, "asset_type": "ai_image" | "ai_video" | "stock_video" | "chart" | "map" | "screen_recording", "fact_check_needed": boolean }
  ]
}`;

return [{ json: { system, input_hash: fnv1a(system) } }];

const raw = $input.first().json["Claude's shot list JSON"] || '';
let parsed = null;
let parseError = null;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parseError = e.message;
}
if (parseError || !Array.isArray(parsed?.shots) || parsed.shots.length === 0) {
  throw new Error('Could not parse a valid shot list JSON (needs a non-empty "shots" array). Paste error: ' + (parseError || 'no shots array found'));
}
return [{ json: { shots: parsed.shots, raw_text: raw } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('Shot list insert failed — no row returned.');
}
const row = items[0].json;
return [{ json: { shot_list_id: row.id, shots: row.shots } }];

const shots = $('Pick Shot List Row').first().json.shots;
const videoId = $('Pick Video Row').first().json.id;
return shots.map((shot, idx) => ({
  json: {
    video_id: videoId,
    shot_index: idx,
    description: shot.description,
    asset_type: shot.asset_type,
    start_seconds: shot.start_seconds,
    end_seconds: shot.end_seconds,
    fact_check_needed: !!shot.fact_check_needed
  },
  pairedItem: { item: 0 }
}));

const shotData = $('Split Out Shots').item.json;
const resp = $input.first().json;
const videos = Array.isArray(resp.videos) ? resp.videos : [];
let fileUrl = null;
if (videos.length > 0) {
  const files = videos[0].video_files || [];
  const hd = files.find(f => f.quality === 'hd') || files[0];
  fileUrl = hd ? hd.link : null;
}
return [{ json: {
  video_id: shotData.video_id,
  shot_index: shotData.shot_index,
  asset_type: shotData.asset_type,
  storage_url: fileUrl,
  found: !!fileUrl
} }];

const scriptRaw = $('Pick Script Row').first().json.content;
const cleaned = scriptRaw
  .replace(/\[[A-Z]+\]\s*(\(~?\d+s,?\s*\d*\s*words?\))?/g, '')
  .replace(/\n{2,}/g, '\n\n')
  .trim();
const channel = $('Pick Channel Row').first().json;
// ElevenLabs premade "Rachel" voice — fallback until a channel voice is locked in per 04-CHANNEL-CONFIG.md
const voiceId = channel.tts_voice_id || '21m00Tcm4TlvDq8ikWAM';
return [{ json: { voiceover_text: cleaned, voice_id: voiceId } }];

return [{ json: {
  result: 'Phase 3 (assets + voiceover) complete — stage set to assets_and_voice_ready. Assembly (Creatomate) not yet wired; run it manually once the template_id is ready.',
  topic: $('Pick Topic Row').first().json.topic_title,
  video_id: $('Pick Video Row').first().json.id,
  shot_list_id: $('Pick Shot List Row').first().json.shot_list_id,
  shots_processed: $('Split Out Shots').all().length,
  voice_track_storage_url: 'voice-tracks/' + $('Pick Video Row').first().json.id + '.mp3'
} }];
